import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_20_sparse_problem.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_20_reward_propagation.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_20_reward_hacking.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_20_potential_shaping.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_20_driving_reward_layers.png",f=JSON.parse('{"title":"奖励一直是零，智能体学什么？稀疏奖励与奖励塑形讲透了","description":"强化学习并不要求每一步都有奖励，但学习必须获得足以区分行为好坏的信号。若机械臂只有完成装配才得 1 分，自动驾驶只有整段路线无事故到达才得 1 分，随机策略在训练早期可能从未成功。回放池里几乎全是零奖励，价值目标没有差异，策略就不知道应该增加哪些动作的概率。这不是网络不够深，而是有效经验在探索分布中","frontmatter":{"title":"奖励一直是零，智能体学什么？稀疏奖励与奖励塑形讲透了","description":"强化学习并不要求每一步都有奖励，但学习必须获得足以区分行为好坏的信号。若机械臂只有完成装配才得 1 分，自动驾驶只有整段路线无事故到达才得 1 分，随机策略在训练早期可能从未成功。回放池里几乎全是零奖励，价值目标没有差异，策略就不知道应该增加哪些动作的概率。这不是网络不够深，而是有效经验在探索分布中","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":13,"source":"2026-08-13/rl_series_20_sparse_reward_shaping.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_20_sparse_problem.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-20-sparse-reward-shaping"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"奖励一直是零，智能体学什么？稀疏奖励与奖励塑形讲透了"}],["meta",{"property":"og:description","content":"强化学习并不要求每一步都有奖励，但学习必须获得足以区分行为好坏的信号。若机械臂只有完成装配才得 1 分，自动驾驶只有整段路线无事故到达才得 1 分，随机策略在训练早期可能从未成功。回放池里几乎全是零奖励，价值目标没有差异，策略就不知道应该增加哪些动作的概率。这不是网络不够深，而是有效经验在探索分布中"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-20-sparse-reward-shaping"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_20_sparse_problem.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"奖励一直是零，智能体学什么？稀疏奖励与奖励塑形讲透了"}],["meta",{"name":"twitter:description","content":"强化学习并不要求每一步都有奖励，但学习必须获得足以区分行为好坏的信号。若机械臂只有完成装配才得 1 分，自动驾驶只有整段路线无事故到达才得 1 分，随机策略在训练早期可能从未成功。回放池里几乎全是零奖励，价值目标没有差异，策略就不知道应该增加哪些动作的概率。这不是网络不够深，而是有效经验在探索分布中"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_20_sparse_problem.png"}]],"prev":{"text":"连续动作也想用 Q-learning？四条路线终于讲清了","link":"/rl/rl-series-19-continuous-action-value-methods"},"next":{"text":"越意外越值得探索吗？ICM、RND 与“噪声电视”陷阱","link":"/rl/rl-series-21-intrinsic-curiosity-icm"}},"headers":[],"relativePath":"rl/rl-series-20-sparse-reward-shaping.md","filePath":"rl/rl-series-20-sparse-reward-shaping.md","lastUpdated":null}'),d={name:"rl/rl-series-20-sparse-reward-shaping.md"};function p(c,a,_,u,b,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="奖励一直是零-智能体学什么-稀疏奖励与奖励塑形讲透了" tabindex="-1">奖励一直是零，智能体学什么？稀疏奖励与奖励塑形讲透了 <a class="header-anchor" href="#奖励一直是零-智能体学什么-稀疏奖励与奖励塑形讲透了" aria-label="Permalink to &quot;奖励一直是零，智能体学什么？稀疏奖励与奖励塑形讲透了&quot;">​</a></h1><p>强化学习并不要求每一步都有奖励，但学习必须获得足以区分行为好坏的信号。若机械臂只有完成装配才得 1 分，自动驾驶只有整段路线无事故到达才得 1 分，随机策略在训练早期可能从未成功。回放池里几乎全是零奖励，价值目标没有差异，策略就不知道应该增加哪些动作的概率。这不是网络不够深，而是有效经验在探索分布中几乎不可见。</p><p>Sparse Reward（稀疏奖励）通常同时带来两个困难：智能体很难偶然发现成功轨迹，即 Exploration（探索）困难；即使得到一次终点奖励，也很难判断前面哪些状态与动作应当获得贡献，即 Credit Assignment（信用分配）困难。Reward Shaping（奖励塑形）可以增加中间反馈，却也可能把任务悄悄改成“刷分游戏”。本篇讲清奖励密度、塑形公式、策略不变条件、终止漏洞和自动驾驶指标边界。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-稀疏不等于延迟" tabindex="-1">1.1 稀疏不等于延迟 <a class="header-anchor" href="#_1-1-稀疏不等于延迟" aria-label="Permalink to &quot;1.1 稀疏不等于延迟&quot;">​</a></h3><p>延迟奖励强调反馈与动作相隔很久；稀疏奖励强调大多数转移的奖励为零或无信息。二者经常同时出现，但对应的诊断与改进并不完全相同。</p><h3 id="_1-2-奖励塑形是改变训练信号" tabindex="-1">1.2 奖励塑形是改变训练信号 <a class="header-anchor" href="#_1-2-奖励塑形是改变训练信号" aria-label="Permalink to &quot;1.2 奖励塑形是改变训练信号&quot;">​</a></h3><p>额外加入距离、速度、进度或舒适性奖励，会改变智能体实际优化的标量目标。塑形项不是“提示语”，而是进入回报、价值和策略梯度的数学量。</p><h3 id="_1-3-稠密奖励可能产生错误最优行为" tabindex="-1">1.3 稠密奖励可能产生错误最优行为 <a class="header-anchor" href="#_1-3-稠密奖励可能产生错误最优行为" aria-label="Permalink to &quot;1.3 稠密奖励可能产生错误最优行为&quot;">​</a></h3><p>距离目标越近就加分，可能诱导智能体在目标附近来回刷进度；每存活一步加分，可能让它拖延结束；惩罚碰撞却不奖励前进，可能让车辆原地不动。</p><h3 id="_1-4-基于势函数的塑形有明确条件" tabindex="-1">1.4 基于势函数的塑形有明确条件 <a class="header-anchor" href="#_1-4-基于势函数的塑形有明确条件" aria-label="Permalink to &quot;1.4 基于势函数的塑形有明确条件&quot;">​</a></h3><p>Potential-Based Reward Shaping（基于势函数的奖励塑形）使用状态势能差 (F(s,a,s&#39;)=\\gamma\\Phi(s&#39;)-\\Phi(s))。在经典 MDP（马尔可夫决策过程）条件和正确边界处理下，它可改变学习速度而保持最优策略集合。</p><p><img src="'+h+'" alt="稀疏奖励的探索与信用分配双重困难"></p><h2 id="二、什么叫奖励稀疏" tabindex="-1">二、什么叫奖励稀疏 <a class="header-anchor" href="#二、什么叫奖励稀疏" aria-label="Permalink to &quot;二、什么叫奖励稀疏&quot;">​</a></h2><h3 id="_2-1-大部分转移得到相同反馈" tabindex="-1">2.1 大部分转移得到相同反馈 <a class="header-anchor" href="#_2-1-大部分转移得到相同反馈" aria-label="Permalink to &quot;2.1 大部分转移得到相同反馈&quot;">​</a></h3><p>若每一步奖励都为零，只有成功时为 1，失败轨迹之间没有直接差异。智能体无法仅凭局部样本知道“差一点成功”和“完全走反”哪一个更好。</p><h3 id="_2-2-成功事件在探索分布中概率极低" tabindex="-1">2.2 成功事件在探索分布中概率极低 <a class="header-anchor" href="#_2-2-成功事件在探索分布中概率极低" aria-label="Permalink to &quot;2.2 成功事件在探索分布中概率极低&quot;">​</a></h3><p>任务需要连续做对多个动作时，随机成功概率会乘法下降。机械臂先抓取、再对齐、再插入，任一环节失败都拿不到终点奖励。</p><h3 id="_2-3-奖励频率与信息量不是一回事" tabindex="-1">2.3 奖励频率与信息量不是一回事 <a class="header-anchor" href="#_2-3-奖励频率与信息量不是一回事" aria-label="Permalink to &quot;2.3 奖励频率与信息量不是一回事&quot;">​</a></h3><p>每一步都给一个常数奖励虽然稠密，却不能区分动作。真正需要的是与任务进展相关、可被学习且不误导最优目标的信息。</p><h3 id="_2-4-稀疏程度要用数据统计描述" tabindex="-1">2.4 稀疏程度要用数据统计描述 <a class="header-anchor" href="#_2-4-稀疏程度要用数据统计描述" aria-label="Permalink to &quot;2.4 稀疏程度要用数据统计描述&quot;">​</a></h3><p>应记录非零奖励转移比例、成功回合比例、首次成功所需环境步、成功轨迹长度和终点奖励传播范围，而不是只凭感觉说奖励“很稀疏”。</p><h2 id="三、探索为什么首先失效" tabindex="-1">三、探索为什么首先失效 <a class="header-anchor" href="#三、探索为什么首先失效" aria-label="Permalink to &quot;三、探索为什么首先失效&quot;">​</a></h2><h3 id="_3-1-没有成功样本就没有正向目标" tabindex="-1">3.1 没有成功样本就没有正向目标 <a class="header-anchor" href="#_3-1-没有成功样本就没有正向目标" aria-label="Permalink to &quot;3.1 没有成功样本就没有正向目标&quot;">​</a></h3><p>价值学习的 Bellman（贝尔曼）目标来自观察到的奖励与下一状态价值。若缓冲区从未出现成功，网络只能学习“所有地方都差不多”。</p><h3 id="_3-2-随机动作难以形成长序列" tabindex="-1">3.2 随机动作难以形成长序列 <a class="header-anchor" href="#_3-2-随机动作难以形成长序列" aria-label="Permalink to &quot;3.2 随机动作难以形成长序列&quot;">​</a></h3><p>单步探索噪声能够改变局部动作，却不保证形成有方向的多步行为。任务跨度越长，偶然到达目标的概率越低。</p><h3 id="_3-3-确定性策略容易固化早期无效行为" tabindex="-1">3.3 确定性策略容易固化早期无效行为 <a class="header-anchor" href="#_3-3-确定性策略容易固化早期无效行为" aria-label="Permalink to &quot;3.3 确定性策略容易固化早期无效行为&quot;">​</a></h3><p>当评论家在近乎相同的零目标上训练，微小近似误差可能成为演员的主要梯度。策略会追逐伪差异，而不是任务成功信号。</p><h3 id="_3-4-增加训练步数未必解决覆盖问题" tabindex="-1">3.4 增加训练步数未必解决覆盖问题 <a class="header-anchor" href="#_3-4-增加训练步数未必解决覆盖问题" aria-label="Permalink to &quot;3.4 增加训练步数未必解决覆盖问题&quot;">​</a></h3><p>若探索机制始终停留在同一区域，再长训练也只是重复收集相似失败。环境步数增加不等于状态空间覆盖改善。</p><h2 id="四、信用分配为什么同样困难" tabindex="-1">四、信用分配为什么同样困难 <a class="header-anchor" href="#四、信用分配为什么同样困难" aria-label="Permalink to &quot;四、信用分配为什么同样困难&quot;">​</a></h2><h3 id="_4-1-终点奖励需要向前传播" tabindex="-1">4.1 终点奖励需要向前传播 <a class="header-anchor" href="#_4-1-终点奖励需要向前传播" aria-label="Permalink to &quot;4.1 终点奖励需要向前传播&quot;">​</a></h3><p>成功回报先更新终点附近状态，再通过多步自举逐渐传播到更早状态。长时域和高折扣会让传播缓慢。</p><h3 id="_4-2-蒙特卡洛回报传播快但方差高" tabindex="-1">4.2 蒙特卡洛回报传播快但方差高 <a class="header-anchor" href="#_4-2-蒙特卡洛回报传播快但方差高" aria-label="Permalink to &quot;4.2 蒙特卡洛回报传播快但方差高&quot;">​</a></h3><p>完整回合回报能把终点奖励直接赋给整条轨迹，却难以区分关键动作与偶然因素，且对轨迹随机性十分敏感。</p><h3 id="_4-3-n-步回报只能改善传播方式" tabindex="-1">4.3 n 步回报只能改善传播方式 <a class="header-anchor" href="#_4-3-n-步回报只能改善传播方式" aria-label="Permalink to &quot;4.3 n 步回报只能改善传播方式&quot;">​</a></h3><p>n-step Return（n 步回报）和 Eligibility Trace（资格迹）在偏差与方差间折中，但不能创造从未被探索到的成功轨迹。</p><h3 id="_4-4-探索与信用分配必须分别验证" tabindex="-1">4.4 探索与信用分配必须分别验证 <a class="header-anchor" href="#_4-4-探索与信用分配必须分别验证" aria-label="Permalink to &quot;4.4 探索与信用分配必须分别验证&quot;">​</a></h3><p>若从目标附近初始化就能学会，问题更可能是探索；若专家成功轨迹仍无法稳定学习，价值传播、状态表示或优化也可能有问题。</p><p><img src="'+l+'" alt="终点奖励沿轨迹向前传播的过程"></p><h2 id="五、奖励塑形到底改变了什么" tabindex="-1">五、奖励塑形到底改变了什么 <a class="header-anchor" href="#五、奖励塑形到底改变了什么" aria-label="Permalink to &quot;五、奖励塑形到底改变了什么&quot;">​</a></h2><h3 id="_5-1-原始任务奖励定义真正目标" tabindex="-1">5.1 原始任务奖励定义真正目标 <a class="header-anchor" href="#_5-1-原始任务奖励定义真正目标" aria-label="Permalink to &quot;5.1 原始任务奖励定义真正目标&quot;">​</a></h3><p>记环境原始奖励为 (r_t^{ext})，它对应任务真正关心的成功、失败、成本或约束结果。</p><h3 id="_5-2-塑形奖励提供额外训练反馈" tabindex="-1">5.2 塑形奖励提供额外训练反馈 <a class="header-anchor" href="#_5-2-塑形奖励提供额外训练反馈" aria-label="Permalink to &quot;5.2 塑形奖励提供额外训练反馈&quot;">​</a></h3><p>训练时常用：</p><p>$$ r_t^{train}=r_t^{ext}+\\beta r_t^{shape} $$</p><p>其中 (\\beta) 控制塑形强度。策略优化的是 (r^{train}) 的累计回报，不会自动优先尊重 (r^{ext})。</p><h3 id="_5-3-奖励权重就是偏好权重" tabindex="-1">5.3 奖励权重就是偏好权重 <a class="header-anchor" href="#_5-3-奖励权重就是偏好权重" aria-label="Permalink to &quot;5.3 奖励权重就是偏好权重&quot;">​</a></h3><p>车道偏差、速度误差、转角变化、碰撞和路线进度被加权求和后，权重直接决定相互取舍。把数值调到“能训练”不代表业务偏好合理。</p><h3 id="_5-4-奖励尺度影响优化动态" tabindex="-1">5.4 奖励尺度影响优化动态 <a class="header-anchor" href="#_5-4-奖励尺度影响优化动态" aria-label="Permalink to &quot;5.4 奖励尺度影响优化动态&quot;">​</a></h3><p>奖励放大会改变价值范围、梯度尺度、熵正则相对强度和裁剪行为。算法对照必须报告所有奖励变换。</p><h2 id="六、直觉塑形为什么容易被利用" tabindex="-1">六、直觉塑形为什么容易被利用 <a class="header-anchor" href="#六、直觉塑形为什么容易被利用" aria-label="Permalink to &quot;六、直觉塑形为什么容易被利用&quot;">​</a></h2><h3 id="_6-1-距离奖励可能鼓励局部徘徊" tabindex="-1">6.1 距离奖励可能鼓励局部徘徊 <a class="header-anchor" href="#_6-1-距离奖励可能鼓励局部徘徊" aria-label="Permalink to &quot;6.1 距离奖励可能鼓励局部徘徊&quot;">​</a></h3><p>若每一步按“离目标近”给正奖励，智能体可能停在近处持续收分，而不是完成任务。</p><h3 id="_6-2-进度奖励可能被往返动作刷取" tabindex="-1">6.2 进度奖励可能被往返动作刷取 <a class="header-anchor" href="#_6-2-进度奖励可能被往返动作刷取" aria-label="Permalink to &quot;6.2 进度奖励可能被往返动作刷取&quot;">​</a></h3><p>只奖励正向进度、不对反向变化对称扣回，就可能形成前进一步得分、后退一步重置的循环。</p><h3 id="_6-3-生存奖励可能鼓励拖延" tabindex="-1">6.3 生存奖励可能鼓励拖延 <a class="header-anchor" href="#_6-3-生存奖励可能鼓励拖延" aria-label="Permalink to &quot;6.3 生存奖励可能鼓励拖延&quot;">​</a></h3><p>每存活一步得正分时，成功终止会停止未来奖励。智能体可能学会避免成功或绕远路。</p><h3 id="_6-4-动作惩罚可能压倒任务目标" tabindex="-1">6.4 动作惩罚可能压倒任务目标 <a class="header-anchor" href="#_6-4-动作惩罚可能压倒任务目标" aria-label="Permalink to &quot;6.4 动作惩罚可能压倒任务目标&quot;">​</a></h3><p>对转角、加速度或能耗惩罚过强，会让“什么都不做”成为高分策略。舒适并不等同于完成任务。</p><h3 id="_6-5-代理指标会被优化到失真" tabindex="-1">6.5 代理指标会被优化到失真 <a class="header-anchor" href="#_6-5-代理指标会被优化到失真" aria-label="Permalink to &quot;6.5 代理指标会被优化到失真&quot;">​</a></h3><p>Reward Hacking（奖励投机）不是智能体有恶意，而是优化器忠实放大了奖励定义中的漏洞。训练得分越高，真实任务反而可能越差。</p><p><img src="'+o+'" alt="看似合理的稠密奖励可能产生奖励投机"></p><h2 id="七、基于势函数的塑形怎样工作" tabindex="-1">七、基于势函数的塑形怎样工作 <a class="header-anchor" href="#七、基于势函数的塑形怎样工作" aria-label="Permalink to &quot;七、基于势函数的塑形怎样工作&quot;">​</a></h2><h3 id="_7-1-为状态定义一个势函数" tabindex="-1">7.1 为状态定义一个势函数 <a class="header-anchor" href="#_7-1-为状态定义一个势函数" aria-label="Permalink to &quot;7.1 为状态定义一个势函数&quot;">​</a></h3><p>(\\Phi(s)) 可以表示对目标进度的启发式估计，例如到目标的负距离、经典控制器价值近似或子目标完成程度。</p><h3 id="_7-2-塑形项使用折扣势能差" tabindex="-1">7.2 塑形项使用折扣势能差 <a class="header-anchor" href="#_7-2-塑形项使用折扣势能差" aria-label="Permalink to &quot;7.2 塑形项使用折扣势能差&quot;">​</a></h3><p>$$ F(s,a,s&#39;)=\\gamma\\Phi(s&#39;)-\\Phi(s) $$</p><p>新的奖励为：</p><p>$$ r&#39;(s,a,s&#39;)=r(s,a,s&#39;)+F(s,a,s&#39;) $$</p><h3 id="_7-3-累积塑形项发生望远镜消去" tabindex="-1">7.3 累积塑形项发生望远镜消去 <a class="header-anchor" href="#_7-3-累积塑形项发生望远镜消去" aria-label="Permalink to &quot;7.3 累积塑形项发生望远镜消去&quot;">​</a></h3><p>沿轨迹累加折扣后的 (F)，中间势函数相互抵消，主要留下初始势能与终端边界项。因此动作价值发生结构化平移，而动作之间的最优排序在理论条件下保持不变。</p><h3 id="_7-4-折扣因子不能随意省略" tabindex="-1">7.4 折扣因子不能随意省略 <a class="header-anchor" href="#_7-4-折扣因子不能随意省略" aria-label="Permalink to &quot;7.4 折扣因子不能随意省略&quot;">​</a></h3><p>直接使用 (\\Phi(s&#39;)-\\Phi(s)) 在 (\\gamma&lt;1) 的任务中不满足相同推导。公式中的折扣必须与任务回报定义一致。</p><p><img src="'+n+'" alt="基于势函数的奖励塑形及望远镜消去"></p><h2 id="八、策略不变保证有哪些前提" tabindex="-1">八、策略不变保证有哪些前提 <a class="header-anchor" href="#八、策略不变保证有哪些前提" aria-label="Permalink to &quot;八、策略不变保证有哪些前提&quot;">​</a></h2><h3 id="_8-1-状态和转移必须符合所用理论模型" tabindex="-1">8.1 状态和转移必须符合所用理论模型 <a class="header-anchor" href="#_8-1-状态和转移必须符合所用理论模型" aria-label="Permalink to &quot;8.1 状态和转移必须符合所用理论模型&quot;">​</a></h3><p>经典结论建立在 MDP、固定折扣和特定奖励变换上。部分可观测、非平稳或多目标系统不能无条件套用。</p><h3 id="_8-2-终止状态势能要正确处理" tabindex="-1">8.2 终止状态势能要正确处理 <a class="header-anchor" href="#_8-2-终止状态势能要正确处理" aria-label="Permalink to &quot;8.2 终止状态势能要正确处理&quot;">​</a></h3><p>回合终止会截断未来项。若不同终点保留不同未抵消势能，最优策略可能改变。常见做法是令真正终止状态势能为零，或按采用的时间限制模型严格推导。</p><h3 id="_8-3-时间截断不等于自然终止" tabindex="-1">8.3 时间截断不等于自然终止 <a class="header-anchor" href="#_8-3-时间截断不等于自然终止" aria-label="Permalink to &quot;8.3 时间截断不等于自然终止&quot;">​</a></h3><p>因最大步数截断的状态仍可能有未来价值。把 Time Limit（时间限制）错误视为吸收终止，会同时污染 Bellman 目标与势函数边界。</p><h3 id="_8-4-函数逼近下学习路径仍会变化" tabindex="-1">8.4 函数逼近下学习路径仍会变化 <a class="header-anchor" href="#_8-4-函数逼近下学习路径仍会变化" aria-label="Permalink to &quot;8.4 函数逼近下学习路径仍会变化&quot;">​</a></h3><p>策略不变是关于理想最优解的性质，不承诺有限数据、神经网络和特定优化器一定收敛，也不保证塑形后训练必然更快。</p><h3 id="_8-5-势函数本身仍需要领域知识" tabindex="-1">8.5 势函数本身仍需要领域知识 <a class="header-anchor" href="#_8-5-势函数本身仍需要领域知识" aria-label="Permalink to &quot;8.5 势函数本身仍需要领域知识&quot;">​</a></h3><p>塑形安全性不等于势函数容易设计。糟糕的势函数可能保留最终最优策略，却让学习路径变得更难或产生巨大方差。</p><h2 id="九、怎样把奖励拆成可审计结构" tabindex="-1">九、怎样把奖励拆成可审计结构 <a class="header-anchor" href="#九、怎样把奖励拆成可审计结构" aria-label="Permalink to &quot;九、怎样把奖励拆成可审计结构&quot;">​</a></h2><h3 id="_9-1-分开记录任务奖励与塑形项" tabindex="-1">9.1 分开记录任务奖励与塑形项 <a class="header-anchor" href="#_9-1-分开记录任务奖励与塑形项" aria-label="Permalink to &quot;9.1 分开记录任务奖励与塑形项&quot;">​</a></h3><p>日志中至少保存 (r^{ext})、每个 (r^{shape}_i)、加权总奖励和回合累计值。只记录总分无法判断策略在优化什么。</p><h3 id="_9-2-每个奖励项都要有单位和范围" tabindex="-1">9.2 每个奖励项都要有单位和范围 <a class="header-anchor" href="#_9-2-每个奖励项都要有单位和范围" aria-label="Permalink to &quot;9.2 每个奖励项都要有单位和范围&quot;">​</a></h3><p>横向误差以米计、速度误差以米每秒计、舒适性可能使用加加速度。归一化和裁剪前后的数值范围都应报告。</p><h3 id="_9-3-建立无塑形基线" tabindex="-1">9.3 建立无塑形基线 <a class="header-anchor" href="#_9-3-建立无塑形基线" aria-label="Permalink to &quot;9.3 建立无塑形基线&quot;">​</a></h3><p>即使稀疏基线学不会，也要保留它作为真实目标参照。塑形方案之间还应进行逐项消融。</p><h3 id="_9-4-单独计算任务成功指标" tabindex="-1">9.4 单独计算任务成功指标 <a class="header-anchor" href="#_9-4-单独计算任务成功指标" aria-label="Permalink to &quot;9.4 单独计算任务成功指标&quot;">​</a></h3><p>成功率、碰撞率、越界率、耗时、路径效率和舒适性应直接从轨迹计算，不能用训练奖励代替。</p><h2 id="十、稀疏奖励还有哪些解决路线" tabindex="-1">十、稀疏奖励还有哪些解决路线 <a class="header-anchor" href="#十、稀疏奖励还有哪些解决路线" aria-label="Permalink to &quot;十、稀疏奖励还有哪些解决路线&quot;">​</a></h2><h3 id="_10-1-改进多步价值传播" tabindex="-1">10.1 改进多步价值传播 <a class="header-anchor" href="#_10-1-改进多步价值传播" aria-label="Permalink to &quot;10.1 改进多步价值传播&quot;">​</a></h3><p>n 步回报、资格迹和更合适的折扣可以加快已发现奖励的传播，但不解决从未成功的问题。</p><h3 id="_10-2-从简单状态开始训练" tabindex="-1">10.2 从简单状态开始训练 <a class="header-anchor" href="#_10-2-从简单状态开始训练" aria-label="Permalink to &quot;10.2 从简单状态开始训练&quot;">​</a></h3><p>Curriculum Learning（课程学习）和 Reverse Curriculum（逆向课程）改变初始状态或任务难度，让成功先在可达区域出现。</p><h3 id="_10-3-重标记已经发生的目标" tabindex="-1">10.3 重标记已经发生的目标 <a class="header-anchor" href="#_10-3-重标记已经发生的目标" aria-label="Permalink to &quot;10.3 重标记已经发生的目标&quot;">​</a></h3><p>Hindsight Experience Replay（事后经验回放，HER）把失败轨迹实际达到的状态当作替代目标，适用于目标条件任务。它不是任意修改奖励，而是利用可重新计算的目标奖励函数。</p><h3 id="_10-4-使用内在动机扩大覆盖" tabindex="-1">10.4 使用内在动机扩大覆盖 <a class="header-anchor" href="#_10-4-使用内在动机扩大覆盖" aria-label="Permalink to &quot;10.4 使用内在动机扩大覆盖&quot;">​</a></h3><p>Curiosity（好奇心）和 Novelty Bonus（新颖性奖励）鼓励访问难预测或少见状态。它们解决探索动力，却可能偏爱随机噪声。</p><h3 id="_10-5-使用专家示范降低搜索难度" tabindex="-1">10.5 使用专家示范降低搜索难度 <a class="header-anchor" href="#_10-5-使用专家示范降低搜索难度" aria-label="Permalink to &quot;10.5 使用专家示范降低搜索难度&quot;">​</a></h3><p>Behavior Cloning（行为克隆）和 Imitation Learning（模仿学习）能提供初始策略或高质量状态分布，但会带来专家偏差与分布漂移问题。</p><h2 id="十一、自动驾驶奖励应怎样设计" tabindex="-1">十一、自动驾驶奖励应怎样设计 <a class="header-anchor" href="#十一、自动驾驶奖励应怎样设计" aria-label="Permalink to &quot;十一、自动驾驶奖励应怎样设计&quot;">​</a></h2><h3 id="_11-1-先写独立成功与失败条件" tabindex="-1">11.1 先写独立成功与失败条件 <a class="header-anchor" href="#_11-1-先写独立成功与失败条件" aria-label="Permalink to &quot;11.1 先写独立成功与失败条件&quot;">​</a></h3><p>到达路线终点、无碰撞、无越界和满足交通规则应有可复现判定。若这些条件本身模糊，奖励权重无法弥补任务定义缺失。</p><h3 id="_11-2-任务目标与安全约束不要混为一项" tabindex="-1">11.2 任务目标与安全约束不要混为一项 <a class="header-anchor" href="#_11-2-任务目标与安全约束不要混为一项" aria-label="Permalink to &quot;11.2 任务目标与安全约束不要混为一项&quot;">​</a></h3><p>把碰撞设为大负分只能表达期望代价，不保证碰撞概率或逐状态安全。安全约束应另有 Shield（安全屏障）、CBF（控制屏障函数）、备用控制器或运行时监控。</p><h3 id="_11-3-不要让前进奖励压过碰撞代价" tabindex="-1">11.3 不要让前进奖励压过碰撞代价 <a class="header-anchor" href="#_11-3-不要让前进奖励压过碰撞代价" aria-label="Permalink to &quot;11.3 不要让前进奖励压过碰撞代价&quot;">​</a></h3><p>长回合累计的小额进度奖励可能大于一次碰撞惩罚。必须根据最大回合长度分析奖励上下界，而不是只看单步权重。</p><h3 id="_11-4-评估真实指标而不是奖励分数" tabindex="-1">11.4 评估真实指标而不是奖励分数 <a class="header-anchor" href="#_11-4-评估真实指标而不是奖励分数" aria-label="Permalink to &quot;11.4 评估真实指标而不是奖励分数&quot;">​</a></h3><p>同一策略在奖励缩放后总分可以任意变化，真实碰撞率和到达率不会因此改变。部署结论只能基于任务与安全指标。</p><p><img src="'+s+'" alt="自动驾驶中训练奖励、任务指标与安全约束的分层"></p><h2 id="十二、一个最小实验怎样设计" tabindex="-1">十二、一个最小实验怎样设计 <a class="header-anchor" href="#十二、一个最小实验怎样设计" aria-label="Permalink to &quot;十二、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_12-1-构造真正稀疏的目标任务" tabindex="-1">12.1 构造真正稀疏的目标任务 <a class="header-anchor" href="#_12-1-构造真正稀疏的目标任务" aria-label="Permalink to &quot;12.1 构造真正稀疏的目标任务&quot;">​</a></h3><p>使用二维导航或简化车道到达任务，只在成功、碰撞或超时给外部奖励，并记录随机策略首次成功概率。</p><h3 id="_12-2-增加直觉稠密奖励" tabindex="-1">12.2 增加直觉稠密奖励 <a class="header-anchor" href="#_12-2-增加直觉稠密奖励" aria-label="Permalink to &quot;12.2 增加直觉稠密奖励&quot;">​</a></h3><p>加入距离、进度和动作平滑项，观察训练是否加快，同时主动搜索徘徊、拖延和原地不动等漏洞。</p><h3 id="_12-3-增加基于势函数的版本" tabindex="-1">12.3 增加基于势函数的版本 <a class="header-anchor" href="#_12-3-增加基于势函数的版本" aria-label="Permalink to &quot;12.3 增加基于势函数的版本&quot;">​</a></h3><p>用相同进度信息构造 (\\gamma\\Phi(s&#39;)-\\Phi(s))，核对自然终止与时间截断的处理差异。</p><h3 id="_12-4-统一评价原始任务指标" tabindex="-1">12.4 统一评价原始任务指标 <a class="header-anchor" href="#_12-4-统一评价原始任务指标" aria-label="Permalink to &quot;12.4 统一评价原始任务指标&quot;">​</a></h3><p>三种奖励都使用相同成功率、碰撞率、轨迹长度和控制平滑度评价，不用塑形总分做横向排名。</p><h3 id="_12-5-做奖励权重敏感性分析" tabindex="-1">12.5 做奖励权重敏感性分析 <a class="header-anchor" href="#_12-5-做奖励权重敏感性分析" aria-label="Permalink to &quot;12.5 做奖励权重敏感性分析&quot;">​</a></h3><p>改变塑形系数和回合长度，检查结论是否稳定，并报告多个随机种子的中位数与失败率。</p><h2 id="十三、最常见的实现错误" tabindex="-1">十三、最常见的实现错误 <a class="header-anchor" href="#十三、最常见的实现错误" aria-label="Permalink to &quot;十三、最常见的实现错误&quot;">​</a></h2><h3 id="_13-1-只保存加权后的总奖励" tabindex="-1">13.1 只保存加权后的总奖励 <a class="header-anchor" href="#_13-1-只保存加权后的总奖励" aria-label="Permalink to &quot;13.1 只保存加权后的总奖励&quot;">​</a></h3><p>一旦策略行为异常，就无法定位是哪一个奖励分量主导了梯度。</p><h3 id="_13-2-训练和评估使用不同成功定义" tabindex="-1">13.2 训练和评估使用不同成功定义 <a class="header-anchor" href="#_13-2-训练和评估使用不同成功定义" aria-label="Permalink to &quot;13.2 训练和评估使用不同成功定义&quot;">​</a></h3><p>若训练奖励按距离阈值判断成功，评估却要求速度、姿态和安全同时满足，曲线之间没有直接可比性。</p><h3 id="_13-3-忘记分析奖励累计上界" tabindex="-1">13.3 忘记分析奖励累计上界 <a class="header-anchor" href="#_13-3-忘记分析奖励累计上界" aria-label="Permalink to &quot;13.3 忘记分析奖励累计上界&quot;">​</a></h3><p>单步小奖励在数百步累积后可能压倒终点奖惩，导致与设计直觉完全相反的最优行为。</p><h3 id="_13-4-势函数塑形漏掉折扣因子" tabindex="-1">13.4 势函数塑形漏掉折扣因子 <a class="header-anchor" href="#_13-4-势函数塑形漏掉折扣因子" aria-label="Permalink to &quot;13.4 势函数塑形漏掉折扣因子&quot;">​</a></h3><p>把公式简化成普通状态差，会破坏经典策略不变条件。</p><h3 id="_13-5-用大碰撞惩罚宣称安全保证" tabindex="-1">13.5 用大碰撞惩罚宣称安全保证 <a class="header-anchor" href="#_13-5-用大碰撞惩罚宣称安全保证" aria-label="Permalink to &quot;13.5 用大碰撞惩罚宣称安全保证&quot;">​</a></h3><p>惩罚只能影响期望优化，不能证明所有状态、所有扰动下均不碰撞。</p><h2 id="十四、学到什么程度才算掌握" tabindex="-1">十四、学到什么程度才算掌握 <a class="header-anchor" href="#十四、学到什么程度才算掌握" aria-label="Permalink to &quot;十四、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_14-1-能区分探索失败与传播失败" tabindex="-1">14.1 能区分探索失败与传播失败 <a class="header-anchor" href="#_14-1-能区分探索失败与传播失败" aria-label="Permalink to &quot;14.1 能区分探索失败与传播失败&quot;">​</a></h3><p>你应能设计从目标附近初始化、加入成功轨迹或检查回报传播的对照实验。</p><h3 id="_14-2-能审计一套奖励函数" tabindex="-1">14.2 能审计一套奖励函数 <a class="header-anchor" href="#_14-2-能审计一套奖励函数" aria-label="Permalink to &quot;14.2 能审计一套奖励函数&quot;">​</a></h3><p>你应能列出每个分量的语义、单位、范围、权重、累计上界与潜在投机行为。</p><h3 id="_14-3-能写出势函数塑形公式和前提" tabindex="-1">14.3 能写出势函数塑形公式和前提 <a class="header-anchor" href="#_14-3-能写出势函数塑形公式和前提" aria-label="Permalink to &quot;14.3 能写出势函数塑形公式和前提&quot;">​</a></h3><p>你应能解释 (\\gamma\\Phi(s&#39;)-\\Phi(s)) 的作用、终止边界以及它不保证有限样本训练成功的原因。</p><h3 id="_14-4-能把奖励分数与真实指标分开" tabindex="-1">14.4 能把奖励分数与真实指标分开 <a class="header-anchor" href="#_14-4-能把奖励分数与真实指标分开" aria-label="Permalink to &quot;14.4 能把奖励分数与真实指标分开&quot;">​</a></h3><p>训练回报、任务成功、安全约束和控制质量必须独立报告。</p><h3 id="_14-5-能进入内在动机" tabindex="-1">14.5 能进入内在动机 <a class="header-anchor" href="#_14-5-能进入内在动机" aria-label="Permalink to &quot;14.5 能进入内在动机&quot;">​</a></h3><p>下一篇将解释 ICM（内在好奇心模块）和 RND（随机网络蒸馏）如何从预测误差产生探索奖励，以及为什么不可预测不等于有价值。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter10/chapter10.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十章稀疏奖励</a></p><p><a href="https://core.ac.uk/display/24286497" target="_blank" rel="noreferrer">Ng、Harada 与 Russell《Policy Invariance under Reward Transformations: Theory and Application to Reward Shaping》</a></p><p><a href="http://incompleteideas.net/book/the-book-2nd.html" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction》第二版</a></p><p><a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro.html" target="_blank" rel="noreferrer">OpenAI Spinning Up 强化学习关键概念</a></p>',155)])])}const P=e(d,[["render",p]]);export{f as __pageData,P as default};
